{
  "framings": [
    {
      "text": "Proposed goal: reduce the feeling that new users are being spammed while keeping onboarding emails in some form.",
      "supports": [
        {
          "source": 1,
          "quote": "I don't want to kill them entirely, I just don't want new users to feel spammed.",
          "occurrence": 0
        }
      ]
    },
    {
      "text": "Proposed outcome: unsubscribe rates stop rising without abandoning the onboarding email program.",
      "supports": [
        {
          "source": 1,
          "quote": "the unsubscribe rate keeps going up.",
          "occurrence": 0
        }
      ]
    }
  ],
  "alternatives": [
    {
      "label": "Reduce the number of emails in the first week",
      "benefit": "Could reduce perceived spamminess and unsubscribes.",
      "cost": "Could remove useful onboarding touchpoints."
    },
    {
      "label": "Keep five emails but make their timing or content more targeted",
      "benefit": "Preserves the program marketing values while potentially reducing annoyance.",
      "cost": "May not solve the problem if frequency itself is the issue."
    },
    {
      "label": "Test different onboarding cadences with new users",
      "benefit": "Could show which balance reduces unsubscribes without relying on assumptions.",
      "cost": "Requires time and enough users for a meaningful comparison."
    }
  ],
  "questions": [
    {
      "text": "When you say you don't want new users to feel spammed, is that the main success criterion, with unsubscribe rate as the signal—or should reducing unsubscribes be the primary goal?",
      "id": "success-criterion"
    }
  ],
  "misfits": [
    "It is unclear whether the main problem is the number of emails, their content, their timing, or some combination."
  ]
}
